public.guard_tenant_organization_id.definition:
CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;

public.fn_entrega_marcar_cancelamento.definition:
CREATE OR REPLACE FUNCTION public.fn_entrega_marcar_cancelamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status::text = 'cancelada'
     AND (TG_OP = 'INSERT' OR OLD.status::text IS DISTINCT FROM 'cancelada') THEN
    IF auth.uid() IS NOT NULL
       AND current_setting('app.entrega_cancelamento_id', true) IS DISTINCT FROM NEW.id::text THEN
      RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_EXIGE_RPC'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    NEW.cancelada_em := COALESCE(NEW.cancelada_em, now());
    NEW.cancelada_por := COALESCE(NEW.cancelada_por, auth.uid());
  END IF;
  RETURN NEW;
END;
$function$;

public.trg_entrega_sync_partner_order_fn.definition:
CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id;

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$;

public.fn_h6c_entrega_ar_b2b_link.definition:
CREATE OR REPLACE FUNCTION public.fn_h6c_entrega_ar_b2b_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_po public.partner_orders%ROWTYPE;
  v_settings record;
BEGIN
  IF NEW.receivable_id IS NULL
     OR NEW.partner_order_id IS NULL
     OR NEW.receivable_id IS NOT DISTINCT FROM OLD.receivable_id THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_po FROM public.partner_orders WHERE id = NEW.partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- 1) o recebível passa a pertencer ao parceiro (entra em saldo_em_aberto)
  UPDATE public.accounts_receivable
     SET partner_id = v_po.partner_id
   WHERE id = NEW.receivable_id AND partner_id IS DISTINCT FROM v_po.partner_id;

  -- 2) vínculo financeiro canônico (idempotente: unique em partner_order_id)
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = v_po.partner_id;
  INSERT INTO public.partner_order_financial_links(
    partner_order_id, partner_id, receivable_id, financial_status, billing_trigger, created_by)
  VALUES (v_po.id, v_po.partner_id, NEW.receivable_id, 'gerado',
          COALESCE(v_settings.billing_trigger, 'entrega'), NEW.billing_generated_by)
  ON CONFLICT (partner_order_id) DO NOTHING;

  -- 3) pedido deixa de ser "comprometido não faturado"
  UPDATE public.partner_orders
     SET financial_status = 'gerado',
         receivable_generated = true,
         receivable_generated_at = COALESCE(receivable_generated_at, now()),
         receivable_generated_by = COALESCE(receivable_generated_by, NEW.billing_generated_by)
   WHERE id = v_po.id AND COALESCE(receivable_generated,false) = false;

  RETURN NEW;
END
$function$;

public.tg_recalc_planning_from_entrega.definition:
CREATE OR REPLACE FUNCTION public.tg_recalc_planning_from_entrega()
 RETURNS trigger
 LANGUAGE plpgsql
